import {validateEntries} from './valuations.js?v=5';
const obj=x=>x&&typeof x==='object'&&!Array.isArray(x);
export function normalizeYear(value){const m=String(value).trim().match(/^(20\d{2})\s*[\/-]\s*(\d{2}|20\d{2})$/);if(!m)throw Error('Usa un curso como 2026/27.');const start=Number(m[1]),end=m[2].length===2?2000+Number(m[2]):Number(m[2]);if(end!==start+1)throw Error('El curso debe abarcar dos años consecutivos.');return `${start}/${String(end).slice(-2)}`;}
export const notebookId=(year,course)=>`n-${normalizeYear(year).slice(0,4)}-${course}`;
export const CORE={1:['mat','lcl','ing','byg','geh','efi','epv','mus'],2:['mat','lcl','ing','fyq','geh','efi','mus','tyd','vec'],3:['mat','lcl','ing','byg','fyq','geh','efi','epv','tyd'],4:['lcl','ing','geh','efi']};
export function createNotebook(course,year,catalog){if(![1,2,3,4].includes(course))throw Error('Curso ESO inválido.');year=normalizeYear(year);const known=new Set(catalog.filter(s=>s.course===course).map(s=>s.id));const choices=[...CORE[course],...(course===1?['fr','cyr']:course===4?['matb']:[])].filter(id=>known.has(id));return {id:notebookId(year,course),year,course,method:'competencies',attention:'atedu',normalized:true,selectedSubjects:choices,atedu:'',grades:{},customSubjects:[]};}
export function validCustom(cs){if(!Array.isArray(cs)||cs.length>100)throw Error('Criterios personalizados inválidos.');const seen=new Set();return cs.map(c=>{if(!obj(c)||typeof c.code!=='string'||!/^\d{1,2}\.\d{1,2}$/.test(c.code)||seen.has(c.code)||typeof c.text!=='string'||!c.text.trim()||c.text.length>2000)throw Error('Criterio personalizado inválido.');seen.add(c.code);return {code:c.code,text:c.text.trim(),competency:Number(c.code.split('.')[0])};});}
export function courseCatalog(all,book){const customs=new Map(book.customSubjects.map(s=>[s.id,s]));return all.filter(s=>s.course===book.course).map(s=>customs.has(s.id)&&s.custom?{...s,...customs.get(s.id)}:s).concat(book.customSubjects.filter(s=>!all.some(a=>a.course===book.course&&a.id===s.id)));}
export function validateBook(b,all){
 if(!obj(b)||![1,2,3,4].includes(b.course)||typeof b.year!=='string'||b.year!==normalizeYear(b.year)||b.id!==notebookId(b.year,b.course)||!['competencies','criteria'].includes(b.method)||!['atedu','religion','none'].includes(b.attention)||typeof b.normalized!=='boolean'||typeof b.atedu!=='string'||b.atedu.length>10000||!obj(b.grades)||!Array.isArray(b.selectedSubjects)||!Array.isArray(b.customSubjects)||b.customSubjects.length>30)throw Error('Cuaderno no válido.');
 const customSubjects=b.customSubjects.map(s=>{if(!obj(s)||typeof s.id!=='string'||! /^(custom-[a-z0-9-]+|alt|pid|rel)$/.test(s.id)||typeof s.name!=='string'||!s.name.trim()||s.name.length>120)throw Error('Materia personalizada inválida.');return {id:s.id,name:s.name.trim(),criteria:validCustom(s.criteria),course:b.course,custom:true,kind:'custom',color:'#9083b0',icon:'✧',pages:[]};});
 if(new Set(customSubjects.map(s=>s.id)).size!==customSubjects.length)throw Error('Materias duplicadas.');
 const book={id:b.id,year:b.year,course:b.course,method:b.method,attention:b.attention,normalized:b.normalized,selectedSubjects:[...b.selectedSubjects],atedu:b.atedu,grades:JSON.parse(JSON.stringify(b.grades)),customSubjects};
 const catalog=courseCatalog(all,book),allowed=new Map(catalog.map(s=>[s.id,new Set(s.criteria.map(c=>c.code))]));
 if(new Set(book.selectedSubjects).size!==book.selectedSubjects.length||book.selectedSubjects.some(id=>typeof id!=='string'||!allowed.has(id)))throw Error('Selección de materias inválida.');
 for(const [sid,cs] of Object.entries(book.grades)){if(!allowed.has(sid)||!obj(cs))throw Error('Materia desconocida en las notas.');for(const [code,ps] of Object.entries(cs)){if(!allowed.get(sid).has(code)||!obj(ps))throw Error('Criterio desconocido en las notas.');for(const [p,v] of Object.entries(ps)){if(!['1','2','3','final'].includes(p))throw Error('Evaluación inválida.');ps[p]=validateEntries(typeof v==='number'?[{id:'legacy-'+p,value:v,label:'Valoración anterior',date:''}]:v);}}}
 return book;
}
export function validateLibrary(raw,all){if(!obj(raw)||![2,3].includes(raw.version)||!Array.isArray(raw.notebooks)||!raw.notebooks.length||raw.notebooks.length>40)throw Error('Formato de copia no compatible.');const notebooks=raw.notebooks.map(b=>validateBook(b,all));if(new Set(notebooks.map(b=>b.id)).size!==notebooks.length||!notebooks.some(b=>b.id===raw.activeId))throw Error('Identificador de cuaderno inválido.');return {version:3,activeId:raw.activeId,notebooks};}
export function migrateV1(raw,all,custom=[]){if(!obj(raw)||raw.version!==1||!['fr','alt'].includes(raw.language))throw Error('Copia antigua no compatible.');const b=createNotebook(1,raw.year,all);b.grades=raw.grades;b.method=raw.method;b.atedu=raw.atedu;if(raw.language==='alt')b.selectedSubjects=b.selectedSubjects.map(x=>x==='fr'?'alt':x);const cs=validCustom(raw.customCriteria||custom);if(cs.length)b.customSubjects=[{id:'alt',name:'Materia Lingüística Transversal',criteria:cs}];return validateLibrary({version:2,activeId:b.id,notebooks:[b]},all);}
export function openNotebook(library,course,year,all){const id=notebookId(year,course);let b=library.notebooks.find(b=>b.id===id);if(!b){if(library.notebooks.length>=40)throw Error('Exporta una copia antes de crear más cuadernos.');b=createNotebook(course,year,all);library.notebooks.push(b)}library.activeId=id;return b;}
export function toggleSubject(book,id,enabled){const list=new Set(book.selectedSubjects);if(enabled){list.add(id);if(id==='mata')list.delete('matb');if(id==='matb')list.delete('mata');if(book.course===1&&id==='fr')list.delete('alt');if(book.course===1&&id==='alt')list.delete('fr');}else list.delete(id);book.selectedSubjects=[...list];}
